update public.fields set verification_status='verified_against_standard', verification_quote='Hinsichtlich Bauart, Einbauort und Funktionsprinzip sind sie zu unterscheiden in: - Systeme mit separater Ableitung von Fremdstoffen; - Systeme mit Rückhaltung von Fremdstoffen innerhalb des Filters in definierten Rückhalteräumen. | Filter, mit dem auf mechanischem Wege mittels eines Filterelements vor dem Zulauf in den Speicher ungelöste Stoffe aus dem Regenwasser entfernt, aus dem Filtergehäuse herausgeführt und einer Versickerungsanlage, einem Vorfluter oder einem Kanal zugeleitet werden | Filter, mit dem auf mechanischem Wege mittels eines Filterelements vor dem Zulauf in den Speicher ungelöste Stoffe aus dem Regenwasser entfernt und vor dem Filter in einem definierten Rückhalteraum zurückgehalten werden — printed p.7, p.4–5', verification_note='md-verified 2026-09-05 (§5.1 + §3.8 Typ C + §3.9 Typ A/B, printed p.7, p.4–5 derived); the two tokens are the two printed system classes; per §3.8/§3.9 the value follows from filtertyp (A/B → Rückhalt, C → Ableitung) — duplicate candidate, STAGED S-2 [VC]', verified_at=now() where id='69513474-19e9-4966-81c4-0735f6b72eb8' and verification_status not in ('verified_against_standard','corrected');

