update public.fields set verification_status='verified_against_standard', verification_quote='$\Sigma_{\text {ges.Festst }} \quad$ Summe der zugegebenen Prüfstoffe; | Tabelle 3 - Prüfstoffe je 1000 Liter Prüfmedium | LDPE-Folie, $15 \mu \mathrm{~m}$ dick & 15 & $150{ }^{\text {a }}$ & $0,15 \mathrm{~g} / \mathrm{l}$ | Quarzsand HFs $250 \mu \mathrm{~m}$ bis $1250 \mu \mathrm{~m}$ & - & 200 & $0,20 \mathrm{~g} / \mathrm{l}$ | ${ }^{\mathrm{a}}$ Die LDPE-Folie geht fiktiv mit $10 \mathrm{~g} /$ Stück in die Massenbilanz ein. — printed p.16, p.15', verification_note='md-verified 2026-09-05 (§6.5.3.1 legend + §6.5.1 Tab. 3, printed p.16, p.15 derived); Tab. 3 fixes 150 g + 150 g (PP-Kugeln, row split across md lines) + 200 g = 500 g per 1000 l → m_ges_festst is derivable from the test-medium volume (hand-enterable derived, STAGED S-8) [VC]', verified_at=now() where id='7340f3b7-b991-41bc-a7b5-0b3440ce6a2b' and verification_status not in ('verified_against_standard','corrected');

-- m_sp_verunr
update public.fields set verification_status='verified_against_standard', verification_quote='$\Sigma_{\text {Sp.verunr }} \quad$ Summe der ermittelten Masseanteile, die in den Speicher eindringt. | Nicht abgetrennte Prüfstoffe sind am Filterablauf mit einem Drahtsieb mit einer Nennmaschenweite von $250 \mu \mathrm{~m}$ nach DIN ISO 3310-1, das zur Nasssiebung geeignet ist, aufzufangen, zu trocknen und zu wägen. — printed p.16', verification_note='md-verified 2026-09-05 (§6.5.3.1 legend + §6.5.2, printed p.16 derived); §6.4.1 prints a 125 µm sieve "nach DIN ISO 3301-1" (typo) for the wet sieving vs 250 µm here — PDF check (STAGED S-9) [VC]', verified_at=now() where id='1d8ce3d4-0bf6-469e-9e68-7ae02c7173f9' and verification_status not in ('verified_against_standard','corrected');

