-- eta_hydr
update public.fields set verification_status='verified_against_standard', verification_quote='Der hydraulische Wirkungsgrad des unbelasteten Filtersystems ist nach Gleichung (3) zu ermitteln: | \eta_{\mathrm{hydr}}=\frac{Q_{\mathrm{Zu}}-Q_{\mathrm{Ab}}}{Q_{\mathrm{Zu}}} \tag{3} | Tabelle 2 - Prüfzeiten für Volumenströme | 100 & 2 | 50 & 2 | 20 & 3 | 10 & 4 | 5 & 8 | 2,5 & 8 | 1 & 8 — printed p.13', verification_note='md-verified 2026-09-05 (§6.4.5 Gl.(3) + Tab. 2, printed p.13 derived); derived field (equation 3); Tab. 2 prescribes seven Q_Zu/Q_Zu,max steps, the encoding holds ONE Q_Zu/Q_Ab pair — the standard reports η as a curve (Bild E.1), single-point simplification noted (STAGED S-8) [VC]', verified_at=now() where id='a539fd83-9eef-4f8a-a1d3-efb97b27f34b' and verification_status not in ('verified_against_standard','corrected');

-- eta_hyd_bel
update public.fields set verification_status='verified_against_standard', verification_quote='Das zunächst unverschmutzte Filtersystem ist mit einem konstant eingestellten Volumenstrom des mit Prüfstoffen versehenen Klarwassers von $30 \%$ des maximalen Volumenstroms $Q_{\mathrm{Zu}, \max }$ über eine Dauer von 4 min zu beaufschlagen. | Anschließend folgen mindestens 10 min Pause. Dieser intermittierende Betrieb erfolgt über 100 Zyklen. | Der hydraulische Wirkungsgrad des dauerbelasteten Filtersystems ist zu ermitteln nach: | \eta_{\text {hyd,bel }}=\frac{Q_{\mathrm{Zu}}-Q_{\mathrm{Ab}}}{Q_{\mathrm{Zu}}} \tag{5} — printed p.14', verification_note='md-verified 2026-09-05 (§6.4.6 Gl.(5), printed p.14 derived); derived field (equation 5); the 30 % / 4 min / ≥10 min / 100 Zyklen protocol has no fields (STAGED S-7h); Gl.(5) legend swaps Q_Zu/Q_Ab wording vs §6.4.5 (STAGED S-9) [VC]', verified_at=now() where id='81e181b8-5ee3-47ea-9545-cfdc6e60ffde' and verification_status not in ('verified_against_standard','corrected');

-- eta_Rueck_AB
update public.fields set verification_status='verified_against_standard', verification_quote='Für die Filter Typ A und Typ B ist die Filtertrennwirkung $\eta_{\text {Rück, } \mathrm{A}, \mathrm{B}}$ zu ermitteln aus: | \eta_{\text {Rück,A,B }}=\frac{\sum_{\text {ges.Festst }}-\sum_{\text {Sp.verunr }}}{\sum_{\text {ges.Festst }}} \tag{7} — printed p.16', verification_note='md-verified 2026-09-05 (§6.5.3.1 Gl.(7), printed p.16 derived); derived field (equation 7); Typ A/B only, yet required=true (STAGED S-6) [VC]', verified_at=now() where id='a07d8f93-3fa5-455e-a05a-26e4d3a3c3dd' and verification_status not in ('verified_against_standard','corrected');

-- eta_Verw
update public.fields set verification_status='verified_against_standard', verification_quote='Hierfür ist analog zur Ermittlung der Speicherverunreinigung in einer parallelen Messung der Quotient aus den in der Abflussleitung gefundenen Fremdstoffmassen (Verwurf) mit der Gesamtmasse an zugegebenen Fremdstoffen zu ermitteln. | \eta_{\text {Verw }}=\frac{\sum_{\text {Verw }}}{\sum_{\text {ges.Festst }}} \tag{8} — printed p.16–17', verification_note='md-verified 2026-09-05 (§6.5.3.2 Gl.(8), printed p.16–17 derived); derived field (equation 8); Typ C only [VC]', verified_at=now() where id='1b4fcd17-2321-4723-baed-111e0de5f498' and verification_status not in ('verified_against_standard','corrected');

-- eta_C
update public.fields set verification_status='verified_against_standard', verification_quote='Es wird das arithmetische Mittel aus ( $\eta_{\text {Rück }}+\eta_{\text {Verw }}$ ) gebildet, folglich gilt: | \eta_{\mathrm{C}}=0,5\left(\eta_{\text {Rück }}+\eta_{\text {Verw }}\right)=0,5 \frac{\Sigma_{\text {ges.Festst }}-\Sigma_{\text {Sp. veruur }}+\Sigma_{\text {Verw }}}{\Sigma_{\text {ges.Festst }}} \tag{9} — printed p.16–17', verification_note='md-verified 2026-09-05 (§6.5.3.2 Gl.(9), printed p.16–17 derived); derived field (equation 9); "Sp. veruur" is an OCR quirk (= Sp.verunr) quoted as printed; Anhang C worked example 0,5·(10−2+7)/10 = 0,75 confirms the composition [VC]', verified_at=now() where id='11fc2f69-0dd0-415c-af4a-2eb1571fe0dd' and verification_status not in ('verified_against_standard','corrected');

-- filtertrennwirkung_nachgewiesen
update public.fields set verification_status='verified_against_standard', verification_quote='Die Filtertrennwirkung ist für Filter mit Zulaufnennweiten $\leq$ DN 200 nachzuweisen. [...] Hinsichtlich der Abtrennung von Fremdstoffen müssen diese Filter einen Wirkungsgrad von mindestens 0,7 erreichen (siehe 6.5.3). — printed p.10', verification_note='md-verified 2026-09-05 (§5.5, printed p.10 derived); the 0,7 limit is §5.5, not §6.5.3 (clause retag STAGED S-4); boolean attestation shadows the computed eta_Rueck_AB / eta_C — numeric gate proposed (STAGED S-7a); the standard defines NO efficiency classes, only this one threshold [VC]', verified_at=now() where id='590083e0-23a5-42bd-9feb-59ed5eeff427' and verification_status not in ('verified_against_standard','corrected');

-- ---------- DIN-1989-2-04 Kennzeichnung, Konformitaetsbewertung und Einbau/Betrieb/Wartung ----------

