-- Gl.(1) V_Rueck_A = Q * 25
update public.equations set verification_quote='Die Filtereinheiten müssen vor den Trennflächen (bei senkrechter Anordnung) oder über den Trennflächen (bei waagrechter Anordnung) ein Einstauvolumen $V_{\text {Rück }}$ nach Gleichung 1 sicherstellen. | V_{\text {Rück }}=Q \times 25 \tag{1} | Dabei ist $V_{\text {Rück }}$ das Einstauvolumen in Liter; Q der Volumenstrom in der planmäßigen Zulaufleitung zum Filter bei einem Füllungsgrad von $70 \%$ und einem Gefälle von 1 \% nach DIN EN 12056-3:2001-01, Tabelle C.1, in Liter je Sekunde 25 Dauer in Sekunden. — printed p.8', verification_note=coalesce(verification_note,'')||' | md-quote 2026-09-05 (§5.3.2 Gl.(1), printed p.8 derived; formula matches the encoded V_Rueck_A = Q * 25; Anhang A prints the criterion as "≥" (minimum); status unchanged — quote backfill only) [VC]' where id='46fb74c9-af5e-4705-8b7e-7c56e595240e' and verification_quote is null;

-- Gl.(2) V_Rueck_B = Q * 2
update public.equations set verification_quote='Das Volumen der herausnehmbaren Behältnisse $V_{\text {Rück }}$ muss mindestens betragen: | V_{\text {Rück }}=Q \times 2 \tag{2} | Dabei ist $V_{\text {Rück }}$ das Einstauvolumen in Liter; $Q$ der Volumenstrom in der planmäßigen Zulaufleitung zum Filter bei einem Füllungsgrad von $70 \%$ und einem Gefälle von 1 \% nach DIN EN 12056-3:2001-01, Tabelle C.1, in Liter je Sekunde; 2 Dauer in Sekunden. — printed p.9', verification_note=coalesce(verification_note,'')||' | md-quote 2026-09-05 (§5.3.3 Gl.(2), printed p.9 derived; formula matches the encoded V_Rueck_B = Q * 2 ("muss mindestens betragen" → minimum); informative Anhang B prints "× 25 s" for Typ B — normative Gl.(2) wins, PDF check advised; status unchanged — quote backfill only) [VC]' where id='f1ac6dff-12fa-43f4-af5b-2b0796ed349b' and verification_quote is null;

-- Gl.(3) eta_hydr = (Q_Zu - Q_Ab) / Q_Zu
update public.equations set verification_quote='Der hydraulische Wirkungsgrad des unbelasteten Filtersystems ist nach Gleichung (3) zu ermitteln: | \eta_{\mathrm{hydr}}=\frac{Q_{\mathrm{Zu}}-Q_{\mathrm{Ab}}}{Q_{\mathrm{Zu}}} \tag{3} | Dabei ist $Q_{\mathrm{Zu}} \quad$ der dem Filtersystem zugeführte Volumenstrom in Liter je Sekunde; $Q_{\mathrm{Ab}} \quad$ der vom Filtersystem in den Ablauf (z. B. Kanal, Versickerungsanlage) abgeführte Volumenstrom in Liter je Sekunde. — printed p.13', verification_note=coalesce(verification_note,'')||' | md-quote 2026-09-05 (§6.4.5 Gl.(3), printed p.13 derived; formula matches the encoded eta_hydr = (Q_Zu - Q_Ab) / Q_Zu; status unchanged — quote backfill only) [VC]' where id='c44be6b5-448a-43f8-9755-ff041c659246' and verification_quote is null;

-- Gl.(4) V_Pruef_leist = Q_Zu_max * 90
update public.equations set verification_quote='Der Vorlagebehälter muss mindestens einem Volumen $V_{\text {Prüf }}$ entsprechen, das dem maximalen Volumenstrom $Q_{\mathrm{Zu}, \max }$ der jeweils vorgegebenen Nennweite des Querschnittes der Zulaufleitung bei $1 \%$ Gefälle, multipliziert mit 90 s entspricht. | V_{\text {Prüf }} \geq Q_{\mathrm{Zu}, \max } \times 90 \tag{4} | Dabei ist $V_{\text {Prüf }} \quad$ Volumen des Vorlagebehälters in Liter; $Q_{\text {Zu,max }} \quad$ maximaler Volumenstrom in Liter je Sekunde; 90 Dauer in Sekunden. — printed p.14', verification_note=coalesce(verification_note,'')||' | md-quote 2026-09-05 (§6.4.6 Gl.(4), printed p.14 derived; printed "≥" — the encoded V_Pruef_leist = Q_Zu_max * 90 computes the minimum; status unchanged — quote backfill only) [VC]' where id='41935d13-1d60-49f6-8308-25d0203c44f0' and verification_quote is null;

-- Gl.(5) eta_hyd_bel = (Q_Zu - Q_Ab) / Q_Zu
update public.equations set verification_quote='Der hydraulische Wirkungsgrad des dauerbelasteten Filtersystems ist zu ermitteln nach: | \eta_{\text {hyd,bel }}=\frac{Q_{\mathrm{Zu}}-Q_{\mathrm{Ab}}}{Q_{\mathrm{Zu}}} \tag{5} | Dabei ist $\eta_{\text {hyd,bel }} \quad$ der hydraulische Wirkungsgrad des dauerbelasteten Systems; $Q_{\mathrm{Ab}} \quad$ der Kanalisation oder der Versickerungsanlage zufließende Volumenstrom; $Q_{\mathrm{Zu}} \quad$ dem Speicher zufließender Volumenstrom. — printed p.14', verification_note=coalesce(verification_note,'')||' | md-quote 2026-09-05 (§6.4.6 Gl.(5), printed p.14 derived; formula matches the encoded eta_hyd_bel = (Q_Zu - Q_Ab) / Q_Zu; the printed legend calls Q_Zu "dem Speicher zufließender Volumenstrom" — inconsistent with §4/§6.4.5 (Q_Zu = to the filter), encoding follows §6.4.5; status unchanged — quote backfill only) [VC]' where id='b6241c7a-4a65-4052-9ea9-9b7704e5d0e1' and verification_quote is null;

-- Gl.(6) V_Pruef_trenn = Q_Zu_max * 180
update public.equations set verification_quote='Der Vorlagebehälter muss mindestens einem Volumen $V_{\text {Prüf }}$ entsprechen, das dem maximalen Volumenstrom $Q_{\text {Zu, max }}$ der jeweils vorgegebenen Nennweite des Querschnittes der Zulaufleitung bei $1 \%$ Gefälle, multipliziert mit 180 s entspricht (Gleichung (6)). | V_{\text {Prüf }} \geq Q_{\text {Zu,max }} \times 180 \tag{6} | Dabei ist $V_{\text {Prüf }} \quad$ Volumen des Vorlagebehälters in Liter; $Q_{\mathrm{Zu} \text { max }} \quad$ maximaler Volumenstrom in Liter je Sekunde; 180 Dauer in Sekunden. — printed p.15', verification_note=coalesce(verification_note,'')||' | md-quote 2026-09-05 (§6.5.1 Gl.(6), printed p.15 derived; printed "≥" — the encoded V_Pruef_trenn = Q_Zu_max * 180 computes the minimum; status unchanged — quote backfill only) [VC]' where id='fd3184a2-6cdb-4498-b78a-083033d12978' and verification_quote is null;

-- Gl.(7) eta_Rueck_AB = (m_ges_festst - m_sp_verunr) / m_ges_festst
update public.equations set verification_quote='Für die Filter Typ A und Typ B ist die Filtertrennwirkung $\eta_{\text {Rück, } \mathrm{A}, \mathrm{B}}$ zu ermitteln aus: | \eta_{\text {Rück,A,B }}=\frac{\sum_{\text {ges.Festst }}-\sum_{\text {Sp.verunr }}}{\sum_{\text {ges.Festst }}} \tag{7} | $\Sigma_{\text {ges.Festst }} \quad$ Summe der zugegebenen Prüfstoffe; $\Sigma_{\text {Sp.verunr }} \quad$ Summe der ermittelten Masseanteile, die in den Speicher eindringt. — printed p.16', verification_note=coalesce(verification_note,'')||' | md-quote 2026-09-05 (§6.5.3.1 Gl.(7), printed p.16 derived; formula matches the encoded eta_Rueck_AB = (m_ges_festst - m_sp_verunr) / m_ges_festst; Anhang A/B worked example (10−3)/10 = 0,7; status unchanged — quote backfill only) [VC]' where id='20c140c2-3bdb-4ed4-937f-b0bded5cd925' and verification_quote is null;

