update public.equations set verification_quote='Hierfür ist analog zur Ermittlung der Speicherverunreinigung in einer parallelen Messung der Quotient aus den in der Abflussleitung gefundenen Fremdstoffmassen (Verwurf) mit der Gesamtmasse an zugegebenen Fremdstoffen zu ermitteln. | \eta_{\text {Verw }}=\frac{\sum_{\text {Verw }}}{\sum_{\text {ges.Festst }}} \tag{8} — printed p.16–17', verification_note=coalesce(verification_note,'')||' | md-quote 2026-09-05 (§6.5.3.2 Gl.(8), printed p.16–17 derived; formula matches the encoded eta_Verw = m_verw / m_ges_festst; Anhang C worked example 7/10 = 0,7; status unchanged — quote backfill only) [VC]' where id='64f61270-2f75-4f4b-8e5d-25893c023e93' and verification_quote is null;

