update public.equations set verification_quote='Es wird das arithmetische Mittel aus ( $\eta_{\text {Rück }}+\eta_{\text {Verw }}$ ) gebildet, folglich gilt: | \eta_{\mathrm{C}}=0,5\left(\eta_{\text {Rück }}+\eta_{\text {Verw }}\right)=0,5 \frac{\Sigma_{\text {ges.Festst }}-\Sigma_{\text {Sp. veruur }}+\Sigma_{\text {Verw }}}{\Sigma_{\text {ges.Festst }}} \tag{9} — printed p.16–17', verification_note=coalesce(verification_note,'')||' | md-quote 2026-09-05 (§6.5.3.2 Gl.(9), printed p.16–17 derived; formula matches the encoded eta_C = 0.5 * (m_ges_festst - m_sp_verunr + m_verw) / m_ges_festst; "Sp. veruur" = OCR of Sp.verunr; Anhang C worked example 0,5·(10−2+7)/10 = 0,75; status unchanged — quote backfill only) [VC]' where id='8c7c52f1-9976-452c-a3c1-cf00131697e6' and verification_quote is null;
